// @dsh-orchestra/delegate：dsh 宿主的委托操作面出口——把 dsh-orchestra skill
// （四宿主单源正文 + dsh 前言）注册进 dsh 会话目录（docs/proposal-dsh-plugin.md §4.1）。
// 形态：cordis 函数插件（named exports: name / apply，无 default export）。
// 纪律：只注册 skill（组合不集成）——零预算判断、零终态分类、零 spawn 决策；
// 一切缺席与残缺静默降级，绝不拖垮宿主。
import { readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Context } from '@deepseek-ai/cordis';

export const name = '@dsh-orchestra/delegate';

// skills 服务缺席（宿主未装 dsh-skill）时 apply 永不执行 = 静默不激活；
// cordis 4 无 inject 声明的服务属性读取会抛错，见 apply 内 duck-typed 兜底
export const inject = ['skills'];

/** 注册载荷 = dsh-skill SkillRegistration 的必填子集（provider 由 registry 盖章） */
interface DelegateSkill {
  name: string;
  description: string;
  content: string;
  /** origin 桶（prompt 可见元数据）：skill 正文随插件包分发 = bundled。
   *  dsh-skill 0.2.2-rc.1 的 register 不校验 source，但 get() 加载校验 string——缺省注册得出不可加载的 skill */
  source: 'bundled';
  invocation: { modelInvocable: boolean; userInvocable: boolean };
  resourceBase: { kind: 'directory'; path: string };
}

/** 宿主接触面收窄：apply 只用这两个成员（测试以 duck-typing mock 驱动，零 cordis 运行时） */
interface MinimalCtx {
  skills?: { register(skill: DelegateSkill): () => void };
  effect?(cleanup: () => void): unknown;
}

interface SkillManifest {
  name: string;
  description: string;
}

export function apply(ctx: Context | MinimalCtx): void {
  try {
    // 闸 1 插件半边（提案 §2）：orchestra 节点会话永不注册，防递归
    if (process.env.ORCH_NODE) return;
    const skills = (ctx as MinimalCtx).skills;
    if (typeof skills?.register !== 'function') return;

    // 包根 = import.meta.url 上一级（src/index.ts 与 dist/index.js 同深度）；
    // assets 为构建产物（源包与 plugins/dsh-delegate 各一份同字节），缺席 = 残包
    const assetsDir = resolve(dirname(fileURLToPath(import.meta.url)), '..', 'assets');
    let manifest: SkillManifest;
    let content: string;
    try {
      manifest = JSON.parse(readFileSync(join(assetsDir, 'skill.json'), 'utf8')) as SkillManifest;
      content = readFileSync(join(assetsDir, 'skill.md'), 'utf8');
    } catch {
      return;
    }
    if (typeof manifest?.name !== 'string' || typeof manifest?.description !== 'string') return;

    const dispose = skills.register({
      name: manifest.name,
      description: manifest.description,
      content,
      source: 'bundled',
      invocation: { modelInvocable: true, userInvocable: true },
      resourceBase: { kind: 'directory', path: assetsDir },
    });
    // 成员调用形态保留 this 绑定（duck-typed 宿主面，node-plugin 同款）。
    // cordis effect 语义：回调立即执行、其返回值才是 disposer——必须返回 dispose 而非调用
    (ctx as MinimalCtx).effect?.(() => dispose);
  } catch {
    // 任何意外失败不拖垮宿主
  }
}
